import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"ResetWObjBuf 复位工件数据队列","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/ResetWObjBuf.md","filePath":"3. 指令/14. 传送带跟随指令/ResetWObjBuf.md","lastUpdated":1778862643000}'),o={name:"3. 指令/14. 传送带跟随指令/ResetWObjBuf.md"};function s(b,t,h,n,i,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="resetwobjbuf-复位工件数据队列" tabindex="-1">ResetWObjBuf 复位工件数据队列 <a class="header-anchor" href="#resetwobjbuf-复位工件数据队列" aria-label="Permalink to &quot;ResetWObjBuf 复位工件数据队列&quot;">​</a></h1><p>该指令为复位已接收到的工件数据队列指令，可以将队列中从外部接收到且未被执行的工件信息清空。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>ResetWObjBuf(Coord, [ResetType], id)</p><p>ResetWObjBuf(坐标系, [复位类型], 视觉 ID 号)</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord</td><td>SYNCOORD 变量</td><td>当前工件位置信息所参考的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>[ResetType]</td><td>enum</td><td>对队列中数据的复位类型：<br>ALL—将队列中已接收到的数据全部清除<br>SELECT—将队列中与复位的视觉 ID 号一致的数据全部清除<br>CURRENT—将队列中的第一个数据清除<br>DEFAULT—缺省类型</td><td>可选，默认 ALL</td></tr><tr><td>id</td><td>int</td><td>队列中需要被复位的 ID 号。仅当 ResetType 设为 SELECT 时该参数才有效</td><td>必填</td></tr></tbody></table>',9)])])}const f=e(o,[["render",s]]);export{u as __pageData,f as default};
